options.customCss:
:root{
  --font-family:'Inter',sans-serif;

  /* Colors */
  --color-background:#f7f8fc;
  --color-card-bg:#ffffff;
  --color-card-border:#eceef5;
  --color-card-shadow:rgba(0,0,0,.06);

  --color-header:#1e293b;
  --color-label:#334155;
  --color-input-text:#475569;
  --color-input-border:#dbe3ee;
  --color-focus-border:#ff6b35;

  --color-submit-btn-bg:#ff6b35;
  --color-submit-btn-text:#ffffff;

  --font-size-header:28px;
  --font-size-label:15px;
  --font-size-input:15px;
  --font-size-body:14px;

  --border-radius:18px;
}

/* Card */
.form-wrapper{
    max-width:850px;
}

/* Inputs */
input,
textarea,
select{
    border-radius:14px !important;
    padding:14px !important;
    transition:.3s ease;
}

input:focus,
textarea:focus,
select:focus{
    box-shadow:0 0 0 4px rgba(255,107,53,.15);
}

/* Button */
button{
    border-radius:14px !important;
    font-weight:600;
    padding:14px 24px !important;
    transition:.3s;
}

button:hover{
    transform:translateY(-2px);
}

