const row = $('Parser + Flatten').first().json;

const headers = Object.keys(row);

let obj = {};

headers.forEach(h => {
  obj[h] = h;
});

obj.spreadsheetId = $('Create spreadsheet').first().json.spreadsheetId;

return [{json: obj}];

